// LUMEN service worker — offline-first cache of the whole game.
// The file list and version are regenerated by `npm run precache`.

const VERSION = 'a81a055571';
const CACHE = `lumen-${VERSION}`;
const PRECACHE = [
  /* PRECACHE:START */
  './',
  './index.html',
  './manifest.json',
  './src/app.js',
  './src/audio/engine.js',
  './src/audio/instruments.js',
  './src/audio/music.js',
  './src/audio/sfx.js',
  './src/audio/sound.js',
  './src/components/board.js',
  './src/components/constellation.js',
  './src/components/icons.js',
  './src/components/melodyBar.js',
  './src/components/prefs.js',
  './src/components/sky.js',
  './src/components/tile.js',
  './src/components/ui.js',
  './src/data/constellations.js',
  './src/data/mechanics.js',
  './src/data/notes.js',
  './src/data/themes.js',
  './src/data/worlds.js',
  './src/game/hints.js',
  './src/game/model.js',
  './src/game/planner.js',
  './src/game/progress.js',
  './src/levels/generator.js',
  './src/levels/index.js',
  './src/levels/melody.js',
  './src/levels/par-table.js',
  './src/levels/recipes.js',
  './src/levels/world1.js',
  './src/main.js',
  './src/screens/daily.js',
  './src/screens/game.js',
  './src/screens/home.js',
  './src/screens/journey.js',
  './src/screens/loading.js',
  './src/screens/settings.js',
  './src/screens/sky.js',
  './src/screens/theme.js',
  './src/screens/world.js',
  './src/screens/worldComplete.js',
  './src/screens/zen.js',
  './src/styles/base.css',
  './src/styles/game.css',
  './src/styles/screens.css',
  './src/utils/dom.js',
  './src/utils/haptics.js',
  './src/utils/rng.js',
  './src/utils/storage.js',
  './assets/fonts/manrope-latin.woff2',
  './assets/icons/apple-touch-icon.png',
  './assets/icons/icon-192.png',
  './assets/icons/icon-512.png',
  './assets/icons/icon.svg',
  './assets/icons/maskable-512.png',
  /* PRECACHE:END */
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('lumen-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // Navigations: serve the cached shell when offline.
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put('./', copy));
          return res;
        })
        .catch(() => caches.match('./').then((r) => r || caches.match('./index.html'))),
    );
    return;
  }
  // Static files: cache first, then network (and remember it).
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(
      (hit) =>
        hit ||
        fetch(req).then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(req, copy));
          }
          return res;
        }),
    ),
  );
});
